package apextest

import (
	"encoding/json"
	"path/filepath"
	"testing"
)

// Original API67 source, metadata and assertions admitted on Salesforce in Wave59.
func TestRunBase64WhitespaceContracts(t *testing.T) {
	root := t.TempDir()
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeBase64Whitespace67.cls"), "@IsTest private class GladeBase64Whitespace67 {\nprivate static void finish(List<Object> rows,Integer expected,String caseName){System.assertEquals(expected,rows.size(),'All discriminator operations retained');String text=JSON.serialize(rows);System.assert(text.length()<2900,'Observation exceeds transport bound');System.assertEquals(expectedRows(caseName),rows,'Exact source-bound Salesforce rows and keysets');}\nprivate static void one(List<Object> rows,String label,String input){Map<String,Object> row=new Map<String,Object>{'label'=>label,'input'=>input,'utf16Length'=>input.length()};try{Blob value=EncodingUtil.base64Decode(input);row.put('returned',true);row.put('hex',EncodingUtil.convertToHex(value));row.put('size',value.size());}catch(Exception e){row.put('type',e.getTypeName());row.put('message',e.getMessage());}rows.add(row);}\n@IsTest static void tabFormFeed(){List<Object> rows=new List<Object>();one(rows,'tab','Z\\tg==');one(rows,'formFeed','Z\\fg==');one(rows,'leadingTab','\\tZg==');one(rows,'trailingFormFeed','Zg==\\f');finish(rows,4,'tabFormFeed');}\n@IsTest static void verticalNonbreaking(){List<Object> rows=new List<Object>();one(rows,'verticalTab','Z'+String.fromCharArray(new List<Integer>{11})+'g==');one(rows,'nonbreakingSpace','Z'+String.fromCharArray(new List<Integer>{160})+'g==');one(rows,'leadingVertical',''+String.fromCharArray(new List<Integer>{11})+'Zg==');one(rows,'trailingNonbreaking','Zg=='+String.fromCharArray(new List<Integer>{160})+'');finish(rows,4,'verticalNonbreaking');}\n@IsTest static void paddingPositions(){List<Object> rows=new List<Object>();one(rows,'onlyPadding','====');one(rows,'interiorPadding','Z=g=');one(rows,'repeatedInterior','Z==m=8=');one(rows,'paddingAfterRemainder','Z===');finish(rows,4,'paddingPositions');}\n@IsTest static void oneSymbolRemainders(){List<Object> rows=new List<Object>();one(rows,'one','A');one(rows,'five','Zm9vA');one(rows,'nine','Zm9vYmFyA');one(rows,'remainderAfterPadding','Zm9v=A=');finish(rows,4,'oneSymbolRemainders');}\n@IsTest static void invalidAfterRemainders(){List<Object> rows=new List<Object>();one(rows,'invalidAfterOne','A!');one(rows,'invalidAfterFive','Zm9vA!');one(rows,'paddingThenInvalid','Zg==!');one(rows,'spaceThenRemainder','Zg== A');finish(rows,4,'invalidAfterRemainders');}\nprivate static List<Object> expectedRows(String caseName){\nif(caseName=='tabFormFeed'){return new List<Object>{new Map<String,Object>{'size'=>1,'hex'=>'66','returned'=>true,'utf16Length'=>5,'input'=>'Z\\tg==','label'=>'tab'},new Map<String,Object>{'size'=>1,'hex'=>'66','returned'=>true,'utf16Length'=>5,'input'=>'Z\\fg==','label'=>'formFeed'},new Map<String,Object>{'size'=>1,'hex'=>'66','returned'=>true,'utf16Length'=>5,'input'=>'\\tZg==','label'=>'leadingTab'},new Map<String,Object>{'size'=>1,'hex'=>'66','returned'=>true,'utf16Length'=>5,'input'=>'Zg==\\f','label'=>'trailingFormFeed'}};}\nif(caseName=='verticalNonbreaking'){return new List<Object>{new Map<String,Object>{'size'=>1,'hex'=>'66','returned'=>true,'utf16Length'=>5,'input'=>'Z'+String.fromCharArray(new List<Integer>{11})+'g==','label'=>'verticalTab'},new Map<String,Object>{'message'=>'Unrecognized base64 character: \u00a0','type'=>'System.StringException','utf16Length'=>5,'input'=>'Z\u00a0g==','label'=>'nonbreakingSpace'},new Map<String,Object>{'size'=>1,'hex'=>'66','returned'=>true,'utf16Length'=>5,'input'=>''+String.fromCharArray(new List<Integer>{11})+'Zg==','label'=>'leadingVertical'},new Map<String,Object>{'message'=>'Unrecognized base64 character: \u00a0','type'=>'System.StringException','utf16Length'=>5,'input'=>'Zg==\u00a0','label'=>'trailingNonbreaking'}};}\nif(caseName=='paddingPositions'){return new List<Object>{new Map<String,Object>{'size'=>0,'hex'=>'','returned'=>true,'utf16Length'=>4,'input'=>'====','label'=>'onlyPadding'},new Map<String,Object>{'size'=>1,'hex'=>'66','returned'=>true,'utf16Length'=>4,'input'=>'Z=g=','label'=>'interiorPadding'},new Map<String,Object>{'size'=>2,'hex'=>'666f','returned'=>true,'utf16Length'=>7,'input'=>'Z==m=8=','label'=>'repeatedInterior'},new Map<String,Object>{'size'=>0,'hex'=>'','returned'=>true,'utf16Length'=>4,'input'=>'Z===','label'=>'paddingAfterRemainder'}};}\nif(caseName=='oneSymbolRemainders'){return new List<Object>{new Map<String,Object>{'size'=>0,'hex'=>'','returned'=>true,'utf16Length'=>1,'input'=>'A','label'=>'one'},new Map<String,Object>{'size'=>3,'hex'=>'666f6f','returned'=>true,'utf16Length'=>5,'input'=>'Zm9vA','label'=>'five'},new Map<String,Object>{'size'=>6,'hex'=>'666f6f626172','returned'=>true,'utf16Length'=>9,'input'=>'Zm9vYmFyA','label'=>'nine'},new Map<String,Object>{'size'=>3,'hex'=>'666f6f','returned'=>true,'utf16Length'=>7,'input'=>'Zm9v=A=','label'=>'remainderAfterPadding'}};}\nif(caseName=='invalidAfterRemainders'){return new List<Object>{new Map<String,Object>{'message'=>'Unrecognized base64 character: !','type'=>'System.StringException','utf16Length'=>2,'input'=>'A!','label'=>'invalidAfterOne'},new Map<String,Object>{'message'=>'Unrecognized base64 character: !','type'=>'System.StringException','utf16Length'=>6,'input'=>'Zm9vA!','label'=>'invalidAfterFive'},new Map<String,Object>{'message'=>'Unrecognized base64 character: !','type'=>'System.StringException','utf16Length'=>5,'input'=>'Zg==!','label'=>'paddingThenInvalid'},new Map<String,Object>{'size'=>2,'hex'=>'6600','returned'=>true,'utf16Length'=>6,'input'=>'Zg== A','label'=>'spaceThenRemainder'}};}\nSystem.assert(false,'Unknown exact case');return null;\n}\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeBase64Whitespace67.cls-meta.xml"), "<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>67.0</apiVersion><status>Active</status></ApexClass>\n")
	writeFile(t, filepath.Join(root, "sfdx-project.json"), "{\"packageDirectories\": [{\"path\": \"force-app\", \"default\": true}], \"sourceApiVersion\": \"67.0\"}")
	run := Run(loadTestIndex(t, root), Options{})
	if got := run.Summary(); got.Total != 5 || got.Passed != 5 || got.Failed != 0 || got.Errors != 0 {
		data, _ := json.Marshal(run)
		t.Fatalf("Exact discriminator contracts: %s", data)
	}
}
